mapper.select:
SELECT s.id AS slot_id, s.schedule_id AS schedule_id, s.organization_id AS organization_id, ao.name AS organization_name, sa.actor_id AS practitioner_id, ap.name AS practitioner_name, sch.healthcare_service_id AS healthcare_service_id, hs.name AS healthcare_service_name, s.start_time AS start_time, s.end_time AS end_time, s.status_code AS status_code, s.capacity AS capacity, s.booked_count AS booked_count, (s.capacity - s.booked_count) AS remaining_count, s.overbooked_flag AS overbooked_flag FROM wkf_slot s INNER JOIN wkf_schedule sch ON s.schedule_id = sch.id AND sch.is_deleted = 0 LEFT JOIN wkf_schedule_actor sa ON sch.id = sa.schedule_id AND sa.actor_type = 1 AND sa.is_deleted = 0 LEFT JOIN adm_organization ao ON s.organization_id = ao.id AND ao.is_deleted = 0 LEFT JOIN adm_practitioner ap ON sa.actor_id = ap.id AND ap.is_deleted = 0 LEFT JOIN adm_healthcare_service hs ON sch.healthcare_service_id = hs.id AND hs.is_deleted = 0 WHERE s.is_deleted = 0
AND s.organization_id = #{query.organizationId}
AND s.schedule_id = #{query.scheduleId}
AND s.start_time >= #{query.date} AND s.start_time < DATE_ADD(#{query.date}, INTERVAL 1 DAY)
AND sa.actor_id = #{query.practitionerId}
AND s.status_code = #{query.statusCode}
ORDER BY s.start_time ASC
